# Section IDs are used for server-rendered, accessible tables of contents.
GUIDES = [
    {
        "slug": "how-to-split-rent-fairly", "category": "START HERE", "icon": "home", "minutes": 6,
        "title": "How to split rent fairly between roommates",
        "short_title": "Find your fair share of the rent",
        "description": "Compare equal, room-size, and income-based rent splits. Use worked examples and a roommate checklist to agree on a fair monthly share.",
        "intro": "A fair rent split starts with an agreement about what each person is paying for. Equal shares can work well, but a bigger bedroom, a private bathroom, or a couple sharing one room can change the conversation.",
        "takeaway": "Choose the rule together, run the numbers, and write the agreement down before anyone commits to a room.",
        "sections": [
            ("choose-a-method", "1. Choose a method that fits your home", '''<p>Start by listing the monthly rent, the people living in the home, and the differences between bedrooms. Compare room size, natural light, storage, bathrooms, parking, and noise. A formula helps make an agreement clear; it cannot decide what everyone values.</p>
<div class="table-wrap"><table><caption>Common rent-splitting methods</caption><thead><tr><th>Method</th><th>How it works</th><th>When it fits</th></tr></thead><tbody><tr><td>Equal split</td><td>Total rent ÷ number of people</td><td>Similar rooms and similar access</td></tr><tr><td>Room-size split</td><td>Part shared equally; part based on private room area</td><td>Bedrooms have different sizes</td></tr><tr><td>Agreed room prices</td><td>Set a price for each room, with the prices adding to the rent</td><td>A bathroom, balcony, or other feature matters</td></tr><tr><td>Income-based split</td><td>Rent follows each person's share of combined income</td><td>Everyone voluntarily agrees to an affordability approach</td></tr></tbody></table></div>'''),
            ("equal-example", "2. Try an equal split first", '''<p>For a $2,400 apartment with three roommates, an equal share is <strong>$2,400 ÷ 3 = $800</strong> per person. If shared utilities are $180, each adds $60, giving a total of $860 per person.</p><p>Keep rent and utilities as separate lines. Rent is usually fixed for the rental period; utilities can vary and may need a different allocation. A person working from home does not automatically owe more: agree on any usage adjustment together.</p><div class="formula">Monthly contribution = rent share + utilities share</div><p>Use the <a href="{{ROOT}}#calculator">rent split calculator</a> to find each person’s equal share of the monthly rent.</p>'''),
            ("adjust-for-rooms", "3. Account for differences between rooms", '''<p>If one bedroom is substantially larger, choose how much of the rent represents shared access and how much represents private space. For example, you might share 40% equally and divide 60% by bedroom area. The 40% is an agreed assumption, not a measured fact about the property's value.</p><p>A private bathroom or parking space can instead have an agreed monthly premium. If one roommate pays $100 more than an equal share, reduce the others' combined shares by $100. A premium must redistribute the fixed total rather than increase it.</p><p>See the <a href="{{ROOT}}guides/split-rent-by-room-size/">room-size formula and worked example</a>. For two people in one room, use the <a href="{{ROOT}}guides/couples-and-shared-rooms/">couples and shared rooms guide</a>.</p>'''),
            ("income-method", "4. Use income only with everyone's agreement", '''<p>An income-based split can suit a household that wants contributions to reflect affordability. If two people earn $3,000 and $2,000 a month, their shares of combined income are 60% and 40%. On $1,500 rent, they would pay $900 and $600.</p><p>Agree whether the income figure means take-home pay, how to handle variable income, and when to review it. Sharing income information should be voluntary. This arrangement is a household choice, not a rule that every roommate must accept.</p>'''),
            ("write-it-down", "5. Write a short roommate agreement", '''<ul><li>Record each person's rent share and the method behind it.</li><li>List which bills are shared and who pays each provider.</li><li>Set a payment date that leaves time before rent is due.</li><li>Agree on deposits, refunds, guests, and partial months separately.</li><li>Choose review triggers: a rent increase, a move-out, or a room change.</li></ul><p>A household agreement may not change what the lease requires. Read the lease and check local rules if responsibilities are unclear. Revisit the arrangement when the facts change rather than assuming the first split will always fit.</p>'''),
        ],
        "faq": [("Does fair always mean equal?", "No. Equal is simple, but differences in private space or an agreed affordability arrangement can justify different shares."), ("Should utilities use the same percentages as rent?", "They can, but they do not have to. An equal per-person utility split is often easier when usage is similar, even when bedrooms have different prices.")],
        "related": ["split-rent-by-room-size", "split-utilities-and-shared-bills"],
    },
    {
        "slug": "split-rent-by-room-size", "category": "ROOM SIZES", "icon": "floorplan", "minutes": 5,
        "title": "How to split rent by room size",
        "short_title": "Different rooms. A balanced split.",
        "description": "Calculate rent using bedroom size and a shared-space allowance, with a complete three-room example and rounding that keeps the total correct.",
        "intro": "A larger bedroom can reasonably cost more without making the whole rent depend on bedroom size. Separating shared access from private space gives you a clear starting point.",
        "takeaway": "Share an agreed portion equally, then allocate the remaining rent by each bedroom's share of total private room area.",
        "sections": [
            ("measure", "1. Measure the private rooms consistently", '''<p>Measure the usable floor area of each bedroom using the same unit. For a rectangular room, multiply length by width. A room measuring 12 feet by 10 feet has an area of 120 square feet. You can use square metres instead; only the ratios matter.</p><p>Decide together whether to include a private closet or bathroom. Do not mix square feet and square metres. Shared kitchens, living rooms, and hallways belong in the shared portion, not in one roommate's bedroom measurement.</p>'''),
            ("formula", "2. Apply the two-part formula", '''<p>Let <strong>R</strong> be total rent, <strong>c</strong> the fraction allocated to shared access, <strong>n</strong> the number of roommates, <strong>Aᵢ</strong> one roommate's room area, and <strong>A</strong> the sum of all bedroom areas. With one person per room:</p><div class="formula">Rent shareᵢ = (R × c ÷ n) + (R × (1 − c) × Aᵢ ÷ A)</div><p>The fraction <em>c</em> is a negotiated assumption. For example, c = 0.40 means 40% of rent is divided equally. It does not claim that common spaces are worth exactly 40% of market rent. A larger shared portion brings the shares closer together.</p>'''),
            ("example", "3. Work through a $2,400 example", '''<p>Three roommates have bedrooms measuring 120, 100, and 80 square feet. Total bedroom area is 300 square feet. They agree to split 40% of rent equally and 60% by room size.</p><p>The shared portion is $960, or $320 each. The private portion is $1,440, allocated in the ratios 120/300, 100/300, and 80/300.</p><div class="table-wrap"><table><caption>Monthly rent by private bedroom area</caption><thead><tr><th>Bedroom</th><th>Shared portion</th><th>Private portion</th><th>Rent share</th></tr></thead><tbody><tr><td>120 sq ft</td><td>$320</td><td>$576</td><td>$896</td></tr><tr><td>100 sq ft</td><td>$320</td><td>$480</td><td>$800</td></tr><tr><td>80 sq ft</td><td>$320</td><td>$384</td><td>$704</td></tr><tr><th>Total</th><td>$960</td><td>$1,440</td><th>$2,400</th></tr></tbody></table></div><p>With $180 of equally shared utilities, each adds $60. The total contributions become $956, $860, and $764. For a quick equal-share comparison, enter $2,400 and three roommates in the <a href="{{ROOT}}#calculator">simple rent calculator</a>.</p>'''),
            ("limits", "4. Adjust for features a measurement misses", '''<p>Area does not capture everything. A quiet room, en suite bathroom, sunny balcony, or reserved parking can matter more than a few square feet. Discuss any fixed adjustment after calculating the baseline and make sure the adjusted shares still add to the total.</p><p>For a couple sharing a bedroom, do not assign the entire room's area to each partner; that double-counts private space. Allocate the private portion once per room, then divide that room's cost between its occupants. The <a href="{{ROOT}}guides/couples-and-shared-rooms/">shared-room guide</a> shows how.</p>'''),
            ("rounding", "5. Resolve the last cent", '''<p>A calculation can produce fractions of a cent. Round down each share to whole cents, then assign the remaining cents to the largest fractional remainders. If remainders tie, use a consistent order and rotate it over time if desired.</p><p>For example, $1,000 divided equally among three people becomes $333.34, $333.33, and $333.33. This is more useful than rounding every share to $333.33 and leaving the household short by a cent. Our calculator reconciles the total automatically.</p>'''),
        ],
        "faq": [("What shared-space percentage should we use?", "There is no universal correct percentage. Agree on a starting point and compare the resulting room prices. This guide uses 40% as an example; your household can agree on a different percentage."), ("Can I use square metres?", "Yes. Use the same unit for every room; the calculation uses proportions, so either square metres or square feet works.")],
        "related": ["how-to-split-rent-fairly", "couples-and-shared-rooms"],
    },
    {
        "slug": "couples-and-shared-rooms", "category": "LIVING TOGETHER", "icon": "people", "minutes": 4,
        "title": "Splitting rent with a couple or a shared bedroom",
        "short_title": "One room, two people. What is fair?",
        "description": "Learn a two-part method for splitting rent when a couple shares a bedroom: private costs by room, shared costs by person, with an example.",
        "intro": "Counting only bedrooms can undercount shared-space use. Counting only people can make two people pay twice for one bedroom. A two-part split helps you account for both.",
        "takeaway": "Allocate private-space rent once per bedroom and shared-space rent once per person. Split each bedroom's private cost among its occupants.",
        "sections": [
            ("two-parts", "1. Separate bedroom access from shared access", '''<p>Choose an agreed fraction of rent for private bedrooms and another for access to the living room, kitchen, and other shared spaces. Divide the shared portion by people. Allocate the private portion by room area or agreed room values, then divide each room's private charge among its occupants.</p><p>This is a negotiation tool. People may value privacy, bathroom access, working space, or household congestion differently. Try the method and discuss the resulting payments before settling on it.</p>'''),
            ("example", "2. Calculate a couple-plus-one example", '''<p>Consider a $2,400 apartment with two equal-sized bedrooms. A couple occupies one and a single roommate occupies the other. They agree that 50% of rent covers shared access and 50% covers bedrooms.</p><ul><li>Shared access: $1,200 ÷ 3 people = $400 per person.</li><li>Private space: $1,200 ÷ 2 equal rooms = $600 per room.</li><li>Each partner pays $400 + $300 = <strong>$700</strong>.</li><li>The single roommate pays $400 + $600 = <strong>$1,000</strong>.</li></ul><p>The couple pays $1,400 together, and the three payments total $2,400. If utilities are $180 and shared equally, each person adds $60. Different room areas or a different shared portion produce a different result.</p>'''),
            ("unequal-rooms", "3. Adjust for unequal bedrooms", '''<p>If the couple's room is larger, use its share of total bedroom area when dividing the private portion. Then divide that room's private charge between the couple. Only count the area once.</p><div class="formula">Person's rent = shared portion ÷ people + their share of their room's private charge</div><p>The homepage calculator divides rent equally by person. Use the steps here when your agreement gives separate values to private rooms and shared access. The <a href="{{ROOT}}guides/split-rent-by-room-size/">room-size guide</a> explains the underlying area calculation.</p>'''),
            ("agreement", "4. Agree on bills, guests, and changes", '''<p>Decide which costs follow people and which follow rooms. Internet can be divided per person; a reserved parking space can go to its user. A couple may choose how they divide their combined payment privately, provided the household receives the agreed total.</p><p>Discuss what happens if an occupant moves out, a partner becomes a permanent resident, or a room changes hands. Set a date for reviewing the split. Also check occupancy terms in the lease: a payment arrangement does not grant permission to add occupants.</p>'''),
        ],
        "faq": [("Should a couple pay exactly double?", "There is no universal rule. Paying twice a single person's share may overvalue access to a single bedroom. A per-room and per-person combination makes the tradeoff explicit."), ("Should both partners pay utilities?", "If utilities are shared per person, each resident contributes. Agree separately on any fixed charges or identifiable individual costs.")],
        "related": ["split-rent-by-room-size", "split-utilities-and-shared-bills"],
    },
    {
        "slug": "split-utilities-and-shared-bills", "category": "SHARED BILLS", "icon": "bolt", "minutes": 5,
        "title": "How to split utilities and shared household bills",
        "short_title": "Keep shared bills simple",
        "description": "Split household utilities by person, usage, or occupancy days. Learn to handle partial months, reimbursements, and cent rounding with examples.",
        "intro": "Utilities feel easier when everyone knows what is shared, how it is divided, and when it is due. Start with the actual bill and keep individual purchases separate.",
        "takeaway": "Use one agreed rule for each type of bill, keep receipts, and reconcile contributions against the provider's actual total.",
        "sections": [
            ("categories", "1. Define the shared bill", '''<p>List rent, electricity, gas, water, internet, and any optional subscriptions separately. A household streaming subscription is not automatically a shared expense if someone never agreed to it. Personal groceries, individual parking, and damage charges should be discussed on their own.</p><p>For a straightforward monthly arrangement, divide an agreed utility total equally among residents. If electricity is $96, water is $42, and internet is $42, the shared total is $180. With three roommates, each contributes $60.</p>'''),
            ("usage", "2. Separate fixed charges from variable usage", '''<p>An equal split works best when usage is broadly comparable. If one person has a clearly identifiable extra cost, agree on an adjustment supported by a meter reading or another reasonable estimate. Avoid treating a guess as an exact measurement.</p><p>A bill may include a standing charge payable even when nobody is home. You can divide that fixed part by all responsible residents and divide only the variable portion using an agreed usage method. Decide this before a holiday or extended absence when possible.</p>'''),
            ("partial-month", "3. Handle a partial month", '''<p>For a per-person-day approach, multiply each person's count of chargeable days by one daily share. Suppose a $150 variable utility bill covers a 30-day period. Two residents count for 30 days each and a third counts for 15 days: total person-days are 75.</p><div class="formula">Person's share = bill × their chargeable days ÷ total person-days</div><p>The two full-month residents pay $60 each; the other pays $30. This assumes the household agreed to charge by these days. Decide whether an absence counts and whether the day of arrival or departure is included.</p><p>Rent proration is a separate question. A common method for one person's established monthly rent share is share × responsible days ÷ days in that calendar month. The lease or local law may require a different method; filling another roommate's vacancy is not automatically everyone's responsibility.</p>'''),
            ("reimbursement", "4. Track what has already been paid", '''<p>If each of three roommates owes $60 in utilities and Alex pays the entire $180 bill, the other two reimburse Alex $60 each. Alex does not also pay another $60 into the household pot; their contribution is already part of the provider payment.</p><p>For multiple bills, calculate <strong>net balance = amount paid − amount owed</strong>. A positive balance means the person should receive money, while a negative balance means they still owe money. Across the household, those balances should sum to zero.</p>'''),
            ("routine", "5. Make a repeatable monthly routine", '''<ul><li>Save the bill and its service dates.</li><li>Record the total, split rule, and amount per person.</li><li>Record payments already made to avoid charging twice.</li><li>Settle by an agreed date and mark reimbursements as paid.</li><li>Carry a rounding cent transparently or assign it consistently.</li></ul><p>The <a href="{{ROOT}}#calculator">homepage calculator</a> handles equal rent shares. Calculate utilities separately using the rules agreed for each bill.</p>'''),
        ],
        "faq": [("Do I owe internet costs while away?", "That depends on your agreement. Internet is often a fixed household charge that continues during an absence, so discuss it separately from usage-based charges."), ("Can we combine every bill into one total?", "Yes, if everyone agrees that all those bills use the same split. Keep bills separate when their participants or allocation methods differ.")],
        "related": ["how-to-split-rent-fairly", "split-restaurant-bill-tax-tip"],
    },
    {
        "slug": "split-restaurant-bill-tax-tip", "category": "AT THE TABLE", "icon": "receipt", "minutes": 5,
        "title": "How to split a restaurant bill with tax and tip",
        "short_title": "Dinner together. Numbers sorted.",
        "description": "Divide restaurant bills equally or by items, allocate actual tax and tip, and avoid double-counting a service charge with a worked example.",
        "intro": "A restaurant bill has more than a food subtotal. Agree on shared dishes, allocate the actual tax, and check whether a service charge or gratuity is already included.",
        "takeaway": "For an itemized split, assign each person's items first, then allocate tax and an agreed tip using a consistent rule. Reconcile against the final receipt.",
        "sections": [
            ("equal-or-itemized", "1. Decide between equal and itemized", '''<p>An equal split is straightforward when orders are similar and everyone agrees. If the final total including tax and the agreed tip is $144, four people pay $36 each.</p><p>An itemized split can work better when one person orders much less or does not share alcohol. Assign each person's items, divide shared dishes among the people who shared them, and allocate discounts before calculating each subtotal. Those subtotals should add up to the discounted food-and-drink total.</p>'''),
            ("tax-tip", "2. Allocate tax and tip consistently", '''<p>When all items have the same tax treatment, one approach is to allocate the receipt's actual tax in proportion to each person's pre-tax subtotal. If a person's items make up 25% of that subtotal, they pay 25% of the tax. Different tax rates or exemptions may require item-level tax instead.</p><p>Agree on the tip amount or percentage and its base. A tip calculated on the pre-tax amount differs from a tip calculated on a tax-inclusive total. Local customs and restaurant policies vary; the example below uses 20% of the pre-tax subtotal as a household choice.</p><div class="formula">Person's total = item subtotal + allocated tax + allocated tip + allocated extra charges</div>'''),
            ("worked-example", "3. Follow an itemized example", '''<p>Three diners have pre-tax item subtotals of $30, $45, and $25, for a $100 subtotal. The actual tax is $8. The group agrees to a $20 tip, equal to 20% of the pre-tax subtotal, and there is no existing service charge.</p><div class="table-wrap"><table><caption>Proportional allocation of a $128 restaurant bill</caption><thead><tr><th>Diner</th><th>Items</th><th>Tax</th><th>Tip</th><th>Total</th></tr></thead><tbody><tr><td>A</td><td>$30.00</td><td>$2.40</td><td>$6.00</td><td>$38.40</td></tr><tr><td>B</td><td>$45.00</td><td>$3.60</td><td>$9.00</td><td>$57.60</td></tr><tr><td>C</td><td>$25.00</td><td>$2.00</td><td>$5.00</td><td>$32.00</td></tr><tr><th>Total</th><td>$100.00</td><td>$8.00</td><td>$20.00</td><th>$128.00</th></tr></tbody></table></div><p>If diners instead agreed to an equal split, the final $128 would divide into $42.67, $42.67, and $42.66. Reconcile the last cent so the server receives the intended total.</p>'''),
            ("service-charge", "4. Read existing charges before adding a tip", '''<p>Look for a service charge, automatic gratuity, delivery fee, or other added charge. Do not assume that every fee is a tip or that a service charge goes directly to the staff. Ask the restaurant when the receipt is unclear.</p><p>If a gratuity is already included and the group decides it covers the intended tip, allocate that charge once. Do not add the same intended tip again automatically. If the group chooses an additional gratuity, record it as an additional amount.</p>'''),
            ("settle", "5. Settle with the person who paid", '''<p>If one diner pays the card total, the others reimburse that diner for their calculated shares. Deduct any cash or deposits already contributed before asking for another payment. Keep the receipt until everyone has settled.</p><p>Find more reading in the <a href="{{ROOT}}resources/#bill-resources">bill-splitting resource collection</a>, or use the same balance method for <a href="{{ROOT}}guides/split-utilities-and-shared-bills/">household reimbursements</a>.</p>'''),
        ],
        "faq": [("Should tip be calculated before or after tax?", "Agree on a base and follow any applicable local practice or restaurant policy. This guide's example uses the pre-tax subtotal; it is not a universal rule."), ("How should shared appetizers be split?", "Divide them among the diners who agreed to share them, then add those portions to each person's item subtotal before allocating tax and tip.")],
        "related": ["split-utilities-and-shared-bills", "how-to-split-rent-fairly"],
    },
    {
        "slug": "divide-a-rent-increase", "category": "WHEN THINGS CHANGE", "icon": "trend", "minutes": 4,
        "title": "How roommates can divide a rent increase fairly",
        "short_title": "New rent. A clear next step.",
        "description": "Compare proportional and equal-dollar rent increases, see a complete example, and learn when roommates should review the original split.",
        "intro": "A rent increase changes the total, but it does not have to restart every discussion from scratch. First check what your current agreement says, then compare the available methods.",
        "takeaway": "Keeping existing percentages preserves the relative room prices. Splitting the increase equally preserves the dollar gaps. Choose deliberately.",
        "sections": [
            ("confirm", "1. Confirm the new rent and effective date", '''<p>Check the written notice, the amount, and the date the change starts. Notice periods, rent limits, and renewal rules depend on the lease and local law. If the notice is unclear or disputed, verify it before treating the new figure as settled.</p><p>Work with the actual increase: <strong>new rent − old rent</strong>. Keep changes to utilities or other charges separate so you can see what is changing.</p>'''),
            ("proportional", "2. Preserve existing percentages", '''<p>Suppose rent rises from $2,400 to $2,550, an increase of $150. Three roommates currently pay $960, $840, and $600: shares of 40%, 35%, and 25%.</p><p>Keeping those percentages gives new payments of $1,020, $892.50, and $637.50. The increases are $60, $52.50, and $37.50. This method preserves the relative pricing of rooms and can fit an arrangement originally based on room differences.</p><div class="formula">New share = old share ÷ old total rent × new total rent</div>'''),
            ("equal-increase", "3. Compare an equal-dollar increase", '''<p>Alternatively, divide the $150 increase equally: $50 per person. New payments become $1,010, $890, and $650. They still add to $2,550, but the percentages change.</p><div class="table-wrap"><table><caption>Two ways to share a $150 rent increase</caption><thead><tr><th>Roommate</th><th>Old share</th><th>Keep percentages</th><th>Add $50 each</th></tr></thead><tbody><tr><td>A</td><td>$960</td><td>$1,020</td><td>$1,010</td></tr><tr><td>B</td><td>$840</td><td>$892.50</td><td>$890</td></tr><tr><td>C</td><td>$600</td><td>$637.50</td><td>$650</td></tr><tr><th>Total</th><td>$2,400</td><td>$2,550</td><td>$2,550</td></tr></tbody></table></div><p>An equal-dollar increase keeps the existing dollar differences between roommates. Neither approach is automatically correct for every home; use the agreement and the reasons behind the original split.</p>'''),
            ("review", "4. Recalculate if the household has changed", '''<p>If someone moved into a larger room, a partner moved in, or a parking space changed hands, simply scaling old shares may preserve an outdated arrangement. Revisit the <a href="{{ROOT}}guides/how-to-split-rent-fairly/">original rent-splitting method</a> with the new facts.</p><p>Confirm each amount, the first payment date, and whether any standing transfer needs updating. Record the revised agreement and check that the payments add to the new rent. A household decision about the split does not change the landlord's rights or the tenants' obligations under the lease.</p>'''),
        ],
        "faq": [("Does the biggest room always take the biggest increase?", "It does when you preserve existing percentages and that room already has the largest share. An equal-dollar increase assigns the same extra amount to each roommate."), ("Should we renegotiate every time rent changes?", "Review the existing agreement first. If rooms, occupants, and the reasons for the original split are unchanged, reusing the agreed method may be sufficient.")],
        "related": ["how-to-split-rent-fairly", "split-rent-by-room-size"],
    },
]
